	ListCalendarMembers(context.Context, *ListCalendarMembersRequest) (*ListCalendarMembersResponse, error)
	UpdateCalendarMemberPermission(context.Context, *UpdateCalendarMemberPermissionRequest) (*UpdateCalendarMemberPermissionResponse, error)
