	SubscribeToCalendar(context.Context, *SubscribeToCalendarRequest) (*SubscribeToCalendarResponse, error)
	UnsubscribeFromCalendar(context.Context, *UnsubscribeFromCalendarRequest) (*UnsubscribeFromCalendarResponse, error)
