	CreateEvent(context.Context, *CreateEventRequest) (*CreateEventResponse, error)
	GetEvent(context.Context, *GetEventRequest) (*GetEventResponse, error)
	ListEventsInRange(context.Context, *ListEventsInRangeRequest) (*ListEventsInRangeResponse, error)
	UpdateEvent(context.Context, *UpdateEventRequest) (*UpdateEventResponse, error)
	DeleteEvent(context.Context, *DeleteEventRequest) (*DeleteEventResponse, error)
	UpdateRecurringEvent(context.Context, *UpdateRecurringEventRequest) (*UpdateRecurringEventResponse, error)
	RSVPToEvent(context.Context, *RSVPToEventRequest) (*RSVPToEventResponse, error)
	ListEventAttendees(context.Context, *ListEventAttendeesRequest) (*ListEventAttendeesResponse, error)
