	CreateEventCategory(context.Context, *CreateEventCategoryRequest) (*CreateEventCategoryResponse, error)
	ListEventCategories(context.Context, *ListEventCategoriesRequest) (*ListEventCategoriesResponse, error)
	DeleteEventCategory(context.Context, *DeleteEventCategoryRequest) (*DeleteEventCategoryResponse, error)
