	CreateResource(context.Context, *CreateResourceRequest) (*CreateResourceResponse, error)
	GetResource(context.Context, *GetResourceRequest) (*GetResourceResponse, error)
	ListResources(context.Context, *ListResourcesRequest) (*ListResourcesResponse, error)
	UpdateResource(context.Context, *UpdateResourceRequest) (*UpdateResourceResponse, error)
	DeleteResource(context.Context, *DeleteResourceRequest) (*DeleteResourceResponse, error)
	ListResourceAvailability(context.Context, *ListResourceAvailabilityRequest) (*ListResourceAvailabilityResponse, error)
	// Resource Booking
	BookResource(context.Context, *BookResourceRequest) (*BookResourceResponse, error)
	CancelBooking(context.Context, *CancelBookingRequest) (*CancelBookingResponse, error)
	ListResourceBookings(context.Context, *ListResourceBookingsRequest) (*ListResourceBookingsResponse, error)
	// Holidays
	ListHolidays(context.Context, *ListHolidaysRequest) (*ListHolidaysResponse, error)
	SeedHolidays(context.Context, *SeedHolidaysRequest) (*SeedHolidaysResponse, error)
	// Preferences
	GetCalendarPreferences(context.Context, *GetCalendarPreferencesRequest) (*GetCalendarPreferencesResponse, error)
	UpdateCalendarPreferences(context.Context, *UpdateCalendarPreferencesRequest) (*UpdateCalendarPreferencesResponse, error)
	// Task Deadlines (calendar overlay)
	ListTaskDeadlinesInRange(context.Context, *ListTaskDeadlinesInRangeRequest) (*ListTaskDeadlinesInRangeResponse, error)
